return function(source)
 assert(source:find('FusionModules.Options.AutoTundra=true',1,true),'Auto Tundra must default on')
 assert(source:find('remotes.TundraBoss',1,true),'native Tundra remotes must be bound')
 assert(source:find('part.Name=="TundraFrostboundSwing"or part.Name=="TundraDragonSwing"',1,true),'only native Tundra combat proxies are selected')
 assert(source:find('part.Parent:FindFirstChild("FireGem")',1,true),'meteor Swing must be identified by its FireGem model')
 assert(source:find('tundra.Remotes.Act:FireServer("Place",value)',1,true),'Firestone placement must use the native Place action')
 assert(source:find('executorTools.WithPromptReach(prompt,math.max(20,prompt.MaxActivationDistance),executorTools.FirePrompt)',1,true),'Firestone placement must trigger the real podium prompt first')
 assert(source:find('character:PivotTo(CFrame.new(point)*root.CFrame.Rotation)',1,true),'Firestone placement must stop at the exact prompt anchor')
 assert(source:find('tundra.GemPlaced(value,beforeGems,beforeMask)',1,true),'Firestone placement must be confirmed before continuing')
 assert(source:find('tundra.Remotes.Act:FireServer("Socket",value)',1,true),'Frost Heart placement must use the native Socket action')
 assert(source:find('tundra.Remotes.Act:FireServer("Travel",direction)',1,true),'Dragon World travel must use the native Travel action')
 assert(source:find('character:PivotTo(target.CFrame)',1,true),'Tundra targets must use Turkey-style exact CFrame following')
 assert(source:find('FusionModules.BatCombat.EventStrike(character,humanoid,eventBats)',1,true),'Tundra combat must rotate owned bats through EventStrike')
 local slick=assert(source:find('if automaticMode and FusionModules.SlickRick.Available()',1,true))
 local tundra=assert(source:find('elseif automaticMode and FusionModules.Tundra.Available()',slick,true))
 local turkey=assert(source:find('elseif automaticMode and FusionModules.TurkeyRampage.Available()',tundra,true))
 assert(slick<tundra and tundra<turkey,'Tundra priority must follow Slick Rick and precede Turkey Rampage')
end
